class Temperature:
    def __init__(self):
        self.__celsius = 0

    def set_celsius(self, value):
        if value < -273.15:
            raise ValueError("below absolute zero")
        self.__celsius = value

    def get_celsius(self):
        return self.__celsius

t = Temperature()
t.set_celsius(25)
print(t.get_celsius())

try:
    t.set_celsius(-300)
except ValueError as e:
    print("ValueError:", e)

print(t.get_celsius())

